export interface CreateProductVariantsInput {
  productId: string;
  name: string;
  sku?: string;
  unitQuantity: string;
  price: string;
  costPrice?: string;
  sortOrder?: number;
  isActive?: boolean;
}
export interface UpdateProductVariantsInput {
  productId?: string;
  name?: string;
  sku?: string;
  unitQuantity?: string;
  price?: string;
  costPrice?: string;
  sortOrder?: number;
  isActive?: boolean;
}

export class ProductVariantsService extends BaseService {
  private static readonly TABLE_NAME = "product_variants";
  private static readonly ENTITY_TYPE: EntityType = "product_variants";
  private static readonly ID_PREFIX = "pv";

  constructor(
    pg: PGlite,
    db: ReturnType<typeof drizzle>,
    syncService: SyncService,
    businessId: string,
    businessUserId: string
  ) {
    super(pg, db, syncService, businessId, businessUserId);
  }

  getEntityType(): EntityType {
    return ProductVariantsService.ENTITY_TYPE;
  }

  getEntityPrefix(): string {
    return ProductVariantsService.ID_PREFIX;
  }

  /**
   * Find a product_variants by ID
   */
  async findById(id: string): Promise<typeof productVariants.$inferSelect | null> {
    const result = await this.db
      .select()
      .from(productVariants)
      .where(eq(productVariants.id, id))
      .limit(1);

    return result[0] || null;
  }

  /**
   * Find all product_variants for the current business
   */
  async findByBusiness(): Promise<typeof productVariants.$inferSelect[]> {
    return this.db
      .select()
      .from(productVariants)
      .where(eq(productVariants.businessId, this.businessId))
      .orderBy(desc(productVariants.createdAt));
  }

  /**
   * Create a new product_variants
   * Stores locally and queues for server sync
   */
  async create(input: CreateProductVariantsInput): Promise<typeof productVariants.$inferSelect> {
    const id = this.generateId();
    const now = this.now();

    const entity: typeof productVariants.$inferInsert = {
      id,
      productId: input.productId,
      name: input.name,
      sku: input.sku,
      unitQuantity: input.unitQuantity,
      price: input.price,
      costPrice: input.costPrice ?? "0",
      sortOrder: input.sortOrder ?? 0,
      isActive: input.isActive ?? true,
      syncStatus: SyncStatus.PENDING,
      syncAttempts: 0,
      businessId: this.businessId,
      createdAt: new Date(now),
      updatedAt: new Date(now),
    };

    await this.db.insert(productVariants).values(entity);

    await this.queueSync("create", id, {
      productId: input.productId,
      name: input.name,
      sku: input.sku,
      unitQuantity: input.unitQuantity,
      price: input.price,
      costPrice: input.costPrice,
      sortOrder: input.sortOrder,
      isActive: input.isActive,
    });

    return { ...entity } as typeof productVariants.$inferSelect;
  }

  /**
   * Update an existing product_variants
   * Updates locally and queues for server sync
   */
  async update(id: string, input: UpdateProductVariantsInput): Promise<void> {
    const existing = await this.findById(id);
    if (!existing) {
      throw new Error(`ProductVariants not found: ${id}`);
    }

    const now = this.now();
    const updateData: Partial<typeof productVariants.$inferInsert> = {
      updatedAt: new Date(now),
      syncStatus: SyncStatus.PENDING,
    };

    if (input.productId !== undefined) {
      updateData.productId = input.productId;
    }

    if (input.name !== undefined) {
      updateData.name = input.name;
    }

    if (input.sku !== undefined) {
      updateData.sku = input.sku;
    }

    if (input.unitQuantity !== undefined) {
      updateData.unitQuantity = input.unitQuantity;
    }

    if (input.price !== undefined) {
      updateData.price = input.price;
    }

    if (input.costPrice !== undefined) {
      updateData.costPrice = input.costPrice;
    }

    if (input.sortOrder !== undefined) {
      updateData.sortOrder = input.sortOrder;
    }

    if (input.isActive !== undefined) {
      updateData.isActive = input.isActive;
    }

    await this.db
      .update(productVariants)
      .set(updateData)
      .where(eq(productVariants.id, id));

    await this.queueSync("update", id, input as Record<string, unknown>);
  }

  /**
   * Delete a product_variants
   * Removes locally and queues deletion for server sync
   */
  async delete(id: string): Promise<void> {
    const existing = await this.findById(id);
    if (!existing) {
      throw new Error(`ProductVariants not found: ${id}`);
    }

    await this.db
      .delete(productVariants)
      .where(eq(productVariants.id, id));

    await this.queueSync("delete", id, {});
  }
}

